let currentOp = 'gt';

function setOp(op) {
    currentOp = op;
    ['gt', 'gte', 'lt', 'lte'].forEach(o => {
        const btn = document.getElementById('op-' + o);
        if (btn) btn.classList.toggle('active', o === op);
    });
    updateLineSim();
}

function updateLineSim() {
    const c = parseInt(document.getElementById('input-bound-c').value, 10);
    document.getElementById('badge-bound-c').innerText = c;

    // Coordinate mapping: 0 is at x=170, step is 30px per unit
    const cx = 170 + c * 30;

    const circle = document.getElementById('bound-circle');
    const ray = document.getElementById('ray-line');
    const pill = document.getElementById('line-readout-pill');

    circle.setAttribute('cx', cx);

    let rayX2 = 330;
    if (currentOp === 'lt' || currentOp === 'lte') {
        ray.setAttribute('x1', 15);
        ray.setAttribute('x2', cx);
    } else {
        ray.setAttribute('x1', cx);
        ray.setAttribute('x2', 330);
    }

    // Fill circle
    const isInclusive = (currentOp === 'gte' || currentOp === 'lte');
    circle.setAttribute('fill', isInclusive ? '#e11d48' : '#1e293b');

    const opSymbols = { 'gt': '>', 'gte': '≥', 'lt': '<', 'lte': '≤' };
    const dotType = isInclusive ? 'solid closed dot' : 'hollow open circle';
    const dir = (currentOp === 'gt' || currentOp === 'gte') ? 'right' : 'left';

    pill.innerHTML = `<i class="fas fa-info-circle" style="color:#60a5fa;"></i> Solution Set: $\{x \in \mathbb{R} \mid x ${opSymbols[currentOp]} ${c}\}$ (${dotType} at ${c}, ray pointing ${dir})`;

    if (window.MathJax && window.MathJax.typesetPromise) {
        window.MathJax.typesetPromise([pill]);
    }
}

document.addEventListener('DOMContentLoaded', () => {
    updateLineSim();
});
